  double nilaiAkhir(Map<String, double> komponen) {
    validasiKomponen(komponen);

    double mitra = komponen['mitra'] ?? 0.0;
    double dosen = komponen['dosen'] ?? 0.0;

    return (0.60 * mitra) + (0.40 * dosen);
  }
}

